INSERT INTO poems (id, title, date, style, theme, meter, dedication, classification, is_pinned, pin_expires_at, urai, notes, variants) VALUES (
  '1772479428127',
  'നിഴൽപാത',
  '2026-03-02T19:23',
  'Free Verse',
  'Longing',
  '',
  '',
  NULL,
  FALSE,
  NULL,
  '',
  '',
  '[{"label": "Original", "title": "നിഴൽപാത", "titleTransliterations": {"en": "Nizhalpaatha", "ta": "நிழ௽பாத"}, "text": "നിഴലതനിൻ പാതൈ ഞാൻ ഇവിടേ, \nനിൻ വിളി പേചും അതൻ നിന്നോചൈ. \nഞാൻ നിൻറനോൻ ഉണ്ടായിരുന്നെങ്കിൽ അവിടേ – \nഒളിച്ചു നിൻ വിചിത്രമായ, ഈ തോന്നൽ ഞാനറിയാ.", "transliterations": {"en": "Nizhalathanin paathai njaan ivide, \nNin vili pechum athan ninnochai. \nNjaan ninranoon undaayirunnengil avide – \nOlichu nin vichithramaya, ee thonnal njaanariya.", "ta": "நிழலதநி௻ பாதை ஞா௻ இவிடே, \nநி௻ விளி பேசுஂ அத௻ நிந்நோசை. \nஞா௻ நி௻றநோ௻ உண்டாயிருந்நெங்கி௽ அவிடே – \nஒளிச்சு நி௻ விசித்ரமாய, ஈ தோந்ந௽ ஞாநறியா."}, "author": "എൽവൻ പാർത്തചാരതി", "lang": "ml"}]'::jsonb
);

INSERT INTO poems (id, title, date, style, theme, meter, dedication, classification, is_pinned, pin_expires_at, urai, notes, variants) VALUES (
  '1772479034777',
  'புதுமாயை',
  '2026-03-02T19:17',
  'Free Verse',
  'Admiration',
  '',
  '',
  NULL,
  FALSE,
  NULL,
  '',
  '',
  '[{"label": "Original", "title": "புதுமாயை", "titleTransliterations": {"en": "Puthumaayai", "ml": "പുതുമായൈ"}, "text": "புறநோக்கு பழக்கமாற்றி,\nநின்னே அறியுமுன்னே கூட்டத்தில் \nதனியே திரியும்...\nகருத்தேறு நவில்வுறு உரையும், \nவலிய மிடுக்கும், என்றும் மிளிரும் இயல்பும், கள்ளமில்லா புன்முறுவலும்.\nவெறும் புறமல்ல, பற்றல்ல,\nஅகத்தில் அரும்பாய்,\nமுன்பில்லா ஓர் புதுமாயை", "transliterations": {"en": "Puranokku pazhakkamaatri,\nNinne ariyumunne koottathil \nThaniye thiriyum...\nKaruthearu navilvuru uraiyum, \nValiya midukkum, enrum milirum iyalpum, kallamilla punmuruvalum.\nVerum puramalla, patralla,\nAgathil arumbaai,\nMunbilla oor puthumaayai", "ml": "പുറനോക്കു പഴക്കമാറ്റി,\nനിഩ്ഩേ അറിയുമുഩ്ഩേ കൂട്ടത്തില് \nതഩിയേ തിരിയുമ്...\nകരുത്തേറു നവില്വുറു ഉരൈയുമ്, \nവലിയ മിടുക്കുമ്, എഩ്റുമ് മിളിരുമ് ഇയല്പുമ്, കള്ളമില്ലാ പുഩ്മുറുവലുമ്.\nവെറുമ് പുറമല്ല, പറ്റല്ല,\nഅകത്തില് അരുമ്പായ്,\nമുഩ്പില്ലാ ഓര് പുതുമായൈ"}, "author": "எல்வன் பார்த்தசாரதி", "lang": "ta"}]'::jsonb
);

INSERT INTO poems (id, title, date, style, theme, meter, dedication, classification, is_pinned, pin_expires_at, urai, notes, variants) VALUES (
  '1772478975043',
  'പുതുമായ',
  '2026-03-02T19:16',
  'Free Verse',
  'Admiration',
  '',
  '',
  NULL,
  FALSE,
  NULL,
  '',
  '',
  '[{"label": "Original", "title": "പുതുമായ", "titleTransliterations": {"en": "Puthumaaya", "ta": "புதுமாய"}, "text": "പുറനോക്കു പഴക്കം മാറ്റി,\nനിന്നെ ഞാൻ അറിയും മുൻപേ നീ കൂട്ടത്തിൽ തനിയെ തിരിഞ്ഞു...\nകരുത്തേറും \nനവിൽവുറു നിൻ ഉരയും, \nവലിയ മിടുക്കും, എന്നും \nമിളീരും ഇയൽപും, കള്ളമില്ലാ പുൻമുറുവലും.\nവെറും പുറമല്ല, പറ്റല്ല—\nഎൻ അകത്തിൽ അരുമ്പായ് നിൻ,\nമുൻപില്ലാ ഓർ പുതു മായ,\nഎനിക്കെന്താകുന്നെന്നറിയാതെ ഞാൻ.", "transliterations": {"en": "Puranokku pazhakkam maatri,\nNinne njaan ariyum munpe nee koottathil thaniye thirinju...\nKarutheerum \nNavilvuru nin urayum, \nValiya midukkum, ennum \nMilirum iyalpum, kallamilla punmuruvalum.\nVerum puramalla, patralla—\nEn akathil arumbaai nin,\nMunbilla oor puthu maaya,\nEnikkenthakunnennariyaathe njaan.", "ta": "புறநோக்கு பழக்கஂ மாற்றி,\nநிந்நெ ஞா௻ அறியுஂ மு௻பே நீ கூட்டத்தி௽ தநியெ திரிஞ்ஞு...\nகருத்தேறுஂ \nநவி௽வுறு நி௻ உரயுஂ, \nவலிய மிடுக்குஂ, எந்நுஂ \nமிளீருஂ இய௽புஂ, கள்ளமில்லா பு௻முறுவலுஂ.\nவெறுஂ புறமல்ல, பற்றல்ல—\nஎ௻ அகத்தி௽ அரும்பாய் நி௻,\nமு௻பில்லா ஓ௼ புது மாய,\nஎநிக்கெந்தாகுந்நெந்நறியாதெ ஞா௻."}, "author": "എൽവൻ പാർത്തചാരതി", "lang": "ml"}]'::jsonb
);

INSERT INTO poems (id, title, date, style, theme, meter, dedication, classification, is_pinned, pin_expires_at, urai, notes, variants) VALUES (
  '1772478880411',
  'நிழலதனின் பாதை',
  '2026-03-02T19:14',
  'Free Verse',
  'Longing',
  '',
  '',
  NULL,
  FALSE,
  NULL,
  '',
  '',
  '[{"label": "Original", "title": "நிழலதனின் பாதை", "titleTransliterations": {"en": "Nizhalathanin Paathai", "ml": "നിഴലതഩിഩ് പാതൈ"}, "text": "நிழலதனின் பாதை யான் இங்கே, \nநின் விளி பேசும் அதன் நின்னோசை. \nயான் நின்றனோன் உறையுமாயின் அங்கே —\nஒளிந்து நின் வியன்மாய, இந் தோன்றல் யானறியா.", "transliterations": {"en": "Nizhalathanin paathai yaan inge, \nNin vizhi paesum athan ninnoosai. \nYaan ninranoon uraiyumaayin angae —\nOlinthu nin viyanmaaya, in thoonral yaanariyaa.", "ml": "നിഴലതഩിഩ് പാതൈ യാഩ് ഇങ്കേ, \nനിഩ് വിളി പേചുമ് അതഩ് നിഩ്ഩോചൈ. \nയാഩ് നിഩ്റഩോഩ് ഉറൈയുമായിഩ് അങ്കേ —\nഒളിന്തു നിഩ് വിയഩ്മായ, ഇന് തോഩ്റല് യാഩറിയാ."}, "author": "எல்வன் பார்த்தசாரதி", "lang": "ta"}, {"label": "Variant", "title": "நிழலதனின் பாதை", "titleTransliterations": {"en": "Nizhalathanin Paathai", "ml": "നിഴലതഩിഩ് പാതൈ"}, "text": "நிழலதனின் பாதை ஞான் இவிடே,\nநின் விளி பேசும் அதன் நின்னோசை.\nஞான் நின்றனோன் உண்டாயிருந்நெங்கில் அவிடே -\nஒளிச்சு நின் விசித்திரமாய, ஈ தோன்னல் ஞானறியா.", "transliterations": {"en": "Nizhalathanin paathai njaan ivide,\nNin vili paesum athan ninnoosai.\nNjaan ninranoon undaayirunnengil avide -\nOlichu nin vichithramaaya, ee thoonnal njaanariyaa.", "ml": "നിഴലതഩിഩ് പാതൈ ഞാഩ് ഇവിടേ,\nനിഩ് വിളി പേചുമ് അതഩ് നിഩ്ഩോചൈ.\nഞാഩ് നിഩ്റഩോഩ് ഉണ്ടായിരുന്നെങ്കില് അവിടേ -\nഒളിച്ചു നിഩ് വിചിത്തിരമായ, ഈ തോഩ്ഩല് ഞാഩറിയാ."}, "author": "எல்வன் பார்த்தசாரதி", "lang": "ta"}]'::jsonb
);

INSERT INTO poems (id, title, date, style, theme, meter, dedication, classification, is_pinned, pin_expires_at, urai, notes, variants) VALUES (
  '1772478778873',
  'வாழ்க்கை',
  '2026-03-02T19:12',
  'Rhyming Verse',
  'Philosophy',
  '',
  '',
  NULL,
  FALSE,
  NULL,
  '',
  '',
  '[{"label": "Original", "title": "Life", "text": "The thing is nowhere — that''s how it goes,\nIt''s the plan you make, that no one knows.\nIt may change from what it''s meant to be,\nThe decision, in the end, it''s all with me.", "author": "Elvan Parthasarathy", "lang": "en"}, {"label": "Translation", "title": "வாழ்க்கை", "titleTransliterations": {"en": "Vaazhkkai"}, "text": "பொருள் எங்கும் இல்லை — இதுவே அதன் வழி,\nயாரும் அறியாத நீ வகுக்கும் விதி.\nஅது மாறலாம் தன் இயல்பில் இருந்து,\nஆனால் முடிவில் சம்மதம் என்னிடமே.", "transliterations": {"en": "Porul engum illai — idhuve athan vazhi,\nYaarum ariyaatha nee vagukkum vidhi.\nAdhu maaralaam than iyalbil irunthu,\nAanaal mudivil sammatham ennidame."}, "author": "எல்வன் பார்த்தசாரதி", "lang": "ta"}]'::jsonb
);

INSERT INTO poems (id, title, date, style, theme, meter, dedication, classification, is_pinned, pin_expires_at, urai, notes, variants) VALUES (
  '1772478654038',
  'மகிழ்ச்சி',
  '2026-03-02T19:10',
  'Free Verse',
  'Happiness',
  '',
  '',
  NULL,
  FALSE,
  NULL,
  '',
  '',
  '[{"label": "Original", "title": "மகிழ்ச்சி", "titleTransliterations": {"en": "Magizhchi", "ml": "മകിഴ്ച്ചി"}, "text": "நன்னதில் வாழ்த்துவும் பிறரை,\nஇதற்கென்னோர் காரணமில்லை.\nஅந்நதில் கிளைக்கும் உணர்வை,\nதருவதற்கோர் வழியுமில்லை.", "transliterations": {"en": "Nannathil vaazhththuvum pirarai,\nItharkennoor kaaranamillai.\nAnnathil kilaikkum unarvai,\nTharuvatharkoor vazhiyumillai.", "ml": "നഩ്ഩതില് വാഴ്ത്തുവുമ് പിറരൈ,\nഇതറ്കെഩ്ഩോര് കാരണമില്ലൈ.\nഅന്നതില് കിളൈക്കുമ് ഉണര്വൈ,\nതരുവതറ്കോര് വഴിയുമില്ലൈ."}, "author": "எல்வன் பார்த்தசாரதி", "lang": "ta"}, {"label": "Translation", "title": "Happiness", "text": "Wishing someone always feels good,\ndoesn''t matter what it''s for.\nJust enjoy spreading a little happiness!", "author": "Elvan Parthasarathy", "lang": "en"}]'::jsonb
);

INSERT INTO poems (id, title, date, style, theme, meter, dedication, classification, is_pinned, pin_expires_at, urai, notes, variants) VALUES (
  '1772478549647',
  'வலிமை',
  '2026-03-02T19:09',
  'Free Verse',
  'Strength',
  '',
  '',
  NULL,
  FALSE,
  NULL,
  '',
  '',
  '[{"label": "Original", "title": "வலிமை", "titleTransliterations": {"en": "Valimai", "ml": "വലിമൈ"}, "text": "நிழல் தேடி நீ செல்கையில்\nஎவரும் வாரா நீயே எல் ஞாயிறாக", "transliterations": {"en": "Nizhal thedi nee selgaiyil\nEvarum vaara neeye el gnaayiraaga", "ml": "നിഴല് തേടി നീ ചെല്കൈയില്\nഎവരുമ് വാരാ നീയേ എല് ഞായിറാക"}, "author": "எல்வன் பார்த்தசாரதி", "lang": "ta"}, {"label": "Translation", "title": "Strength", "text": "As you walk seeking shade, none will come —\nYou must become your own blazing sun", "author": "Elvan Parthasarathy", "lang": "en"}]'::jsonb
);

