  '',
  '',
  '[{"label": "Original", "title": "மறைகவி", "titleTransliterations": {"en": "Maraigavi", "ml": "മറൈകവി"}, "text": "முடிவிலிமேல் காணும் விண்ணு மோர்வானம்\nமுடிவில்லாத் தாரகைக ளோடும் மின்னியதோர் விண்மீன்!\nதூரிகைக ளாயாய் என்மேல் வரைந்த தன்னை\nதூவியத் தூறல்போல் வொளியின் நொலியைக் காணா தன்றே!\n\nஇருதுகள் விசும்பும் இயைந்துருக வினையோருரு\nஒருதுகள் உடையாதுள்ள மிரும்புமறநின் நன்றே!\nஅகத்துக ளோடும் மாரியுரு வொளியின் நொலியை\nமாறிக் கோள்கள் நிற்குஞ்ஞாயி உறுனின் மிளிரும்!\n\nதம்மொழியாள மலையரிச் சுவடிமாறி\nஅழகுறுநின் திரள்கலெல்லா விண்மாய விலையில் மூடி\nநிழலிரு இருளின் மனமது மையல் கொண்டு\nவால்வெள்ளி விண்மீனாக மறையுருவான தன்றே!\n\nமதியாள மதியாகரு வுருவினின் நிழலியொடு\nவிரைசீரூர் நகல்களெல்லா மூவாண்டுக் கள்வனாகி\nமையிருள் தன்னில் வைத்து\nகளிப்பொல்லாங் கான தன்றே!\n\nகருந்துளை தன்னில் விண்கல் மாய\nமைந்திடல் மறையிரும் மரமை மாற\nமதி மயங்கினரு வெளியிரும் தன்மை\nஎரிமலை தன்னுள் கொண்ட தன்றே!\n\nஉரையா திருந்தென்ன உரைந்திருப்பின்\nவாய்த்தனின் வியன்னென்ன மெளியே\nநின்கட்டு மீறிச் சொற்செல்பல\nவீனமாய் என்னின் வதுவே!\n\nஅல்லவை யாவும் யானே\nஉள்ளவை நாளு மின்மை\nதம்மிருள் தன்னின் சேரல்\nயான் மறைகவி நின்றேனே\nநுவ்விருள் தன்னின் மொழி!", "transliterations": {"en": "Mudivilimeal kaanum vinnu moorvaanam\nMudivillaath thaaragaiga loodum minniyathoor vinmeen!\nThoorigaiga laayaai enmeal varaintha thannai\nThooviyath thooralpoal voliyin noliyaiy kaanaa thanre!\n\nIruthugal visumbum iyainthuruga vinaiyooruru\nOruthugal udaiyaathulla mirumbumaranin nanre!\nAgaththuga loodum maariyuru voliyin noliyai\nMaarik koalgal nirkunggnaayi urunin milirum!\n\nThammozhiyaala malaiyarich chuvadimaari\nAzhagurunin thiralkalellaa vinmaaya vilaiyil moodi\nNizhaliru irulin manamathu maiyyal kondu\nVaahlvelli vinmeenaaga maraiyuruvaana thanre!\n\nMathiyaala mathiyaagaru vuruvinin nizhaliyodu\nViraisiroor nagalgalellaa moovaanduk kalvanaagi\nMaiyirul thannil vaiththu\nKalippollaang kaana thanre!\n\nKarunthulai thannil vinkal maaya\nMainthidal maraiyirum maramai maara\nMathi mayanginaru veliyirum thanmai\nErimalai thannul konda thanre!\n\nUraiyaa thirunthenna urainthiruppin\nVaayththanin viyannenna meliye\nNinkattu meerich chorchenpala\nVeenamaai ennin vathuve!\n\nAllavai yaavum yaane\nUllavai naalum inmai\nThammirul thannin saeral\nYaan maraigavi ninrene\nNuvvirul thannin mozhi!", "ml": "മുടിവിലിമേല് കാണുമ് വിണ്ണു മോര്വാഩമ്\nമുടിവില്ലാത് താരകൈക ളോടുമ് മിഩ്ഩിയതോര് വിണ്മീഩ്!\nതൂരികൈക ളായായ് എഩ്മേല് വരൈന്ത തഩ്ഩൈ\nതൂവിയത് തൂറല്പോല് വൊളിയിഩ് നൊലിയൈക് കാണാ തഩ്റേ!\n\nഇരുതുകള് വിചുമ്പുമ് ഇയൈന്തുരുക വിഩൈയോരുരു\nഒരുതുകള് ഉടൈയാതുള്ള മിരുമ്പുമറനിഩ് നഩ്റേ!\nഅകത്തുക ളോടുമ് മാരിയുരു വൊളിയിഩ് നൊലിയൈ\nമാറിക് കോള്കള് നിറ്കുഞ്ഞായി ഉറുഩിഩ് മിളിരുമ്!\n\nതമ്മൊഴിയാള മലൈയരിച് ചുവടിമാറി\nഅഴകുറുനിഩ് തിരള്കലെല്ലാ വിണ്മായ വിലൈയില് മൂടി\nനിഴലിരു ഇരുളിഩ് മഩമതു മൈയല് കൊണ്ടു\nവാല്വെള്ളി വിണ്മീഩാക മറൈയുരുവാഩ തഩ്റേ!\n\nമതിയാള മതിയാകരു വുരുവിഩിഩ് നിഴലിയൊടു\nവിരൈചീരൂര് നകല്കളെല്ലാ മൂവാണ്ടുക് കള്വഩാകി\nമൈയിരുള് തഩ്ഩില് വൈത്തു\nകളിപ്പൊല്ലാങ് കാഩ തഩ്റേ!\n\nകരുന്തുളൈ തഩ്ഩില് വിണ്കല് മായ\nമൈന്തിടല് മറൈയിരുമ് മരമൈ മാറ\nമതി മയങ്കിഩരു വെളിയിരുമ് തഩ്മൈ\nഎരിമലൈ തഩ്ഩുള് കൊണ്ട തഩ്റേ!\n\nഉരൈയാ തിരുന്തെഩ്ഩ ഉരൈന്തിരുപ്പിഩ്\nവായ്ത്തഩിഩ് വിയഩ്ഩെഩ്ഩ മെളിയേ\nനിഩ്കട്ടു മീറിച് ചൊറ്ചെല്പല\nവീഩമായ് എഩ്ഩിഩ് വതുവേ!\n\nഅല്ലവൈ യാവുമ് യാഩേ\nഉള്ളവൈ നാളു മിഩ്മൈ\nതമ്മിരുള് തഩ്ഩിഩ് ചേരല്\nയാഩ് മറൈകവി നിഩ്റേഩേ\nനുവ്വിരുള് തഩ്ഩിഩ് മൊഴി!"}, "author": "எல்வன் பார்த்தசாரதி", "lang": "ta"}]'::jsonb
);

INSERT INTO quotes (id, tag, date, is_pinned, pin_expires_at, urai, notes, variants) VALUES (
  '1772479061127',
  'Philosophy',
  '2026-03-01T10:00',
  FALSE,
  NULL,
  '',
  '',
  '[{"label": "Original", "title": "தத்துவம்", "titleTransliterations": {"en": "Thaththuvam", "ml": "തത്തുവമ്"}, "text": "நெய்யாப் பட்டுநூல்,\nமெழுகைப் போல்.", "transliterations": {"en": "Neiyaap Pattunool,\nMezhugaip Poal.", "ml": "നെയ്യാപ് പട്ടുനൂല്,\nമെഴുകൈപ് പോല്."}, "author": "எல்வன் பார்த்தசாரதி", "lang": "ta"}, {"label": "Original", "title": "Philosophy", "text": "Unwoven silk thread,\nA candle’s light.", "author": "Elvan Parthasarathy", "lang": "en"}, {"label": "Original", "title": "തത്ത്വം", "titleTransliterations": {"en": "Thaththvam", "ta": "தத்த்வஂ"}, "text": "നെയ്യാത്ത പട്ടുനൂൽ\nമെഴുകു പോലെ", "transliterations": {"en": "Neyyaaththa pattunool\nMezhuku poale", "ta": "நெய்யாத்த பட்டுநூ௽\nமெழுகு போலெ"}, "author": "എൽവൻ പാർത്തചാരതി", "lang": "ml"}]'::jsonb
);

INSERT INTO quotes (id, tag, date, is_pinned, pin_expires_at, urai, notes, variants) VALUES (
  '1',
  'Philosophy',
  '2026-03-01T14:00',
  FALSE,
  NULL,
  '',
  '',
  '[{"label": "Original", "title": "தத்துவம்", "titleTransliterations": {"en": "Thaththuvam", "ml": "തത്തുവമ്"}, "text": "நான் ஒன்றுமறியே,\nமனிதர் முற்றுமறியே.\nஎவரும் பிழையற்றோர் அன்று,\nதவரே நிழலாய் நின்றது.", "transliterations": {"en": "Naan onrumariye,\nManithar mutrumariye.\nEvarum pzhaiyatroor anru,\nThavare nizhalaai ninrathu.", "ml": "നാഩ് ഒഩ്റുമറിയേ,\nമഩിതര് മുറ്റുമറിയേ.\nഎവരുമ് പിഴൈയറ്റോര് അഩ്റു,\nതവരേ നിഴലായ് നിഩ്റതു."}, "author": "எல்வன் பார்த்தசாரதி", "lang": "ta"}, {"label": "Translation", "title": "Philosophy", "text": "I know not a single knowing,\nnor mankind ever all-knowing.\nWe are none ever free of flaw —\nit stands beside us evermore,\nlike our reflection on the floor.", "author": "Elvan Parthasarathy", "lang": "en"}]'::jsonb
);

INSERT INTO quotes (id, tag, date, is_pinned, pin_expires_at, urai, notes, variants) VALUES (
  '2',
  'Journey',
  '2026-03-01T18:00',
  FALSE,
  NULL,
  '',
  '',
  '[{"label": "Original", "title": "பயணம்", "titleTransliterations": {"en": "Payanam", "ml": "പയണമ്"}, "text": "முன்னே முடிவின் முடிவு மாறின்,\nமுன்னே முடிவிலா முடிவு நன்னின்", "transliterations": {"en": "Munne mudivin mudivu maarin,\nMunne mudivilaa mudivu nannin", "ml": "മുഩ്ഩേ മുടിവിഩ് മുടിവു മാറിഩ്,\nമുഩ്ഩേ മുടിവിലാ മുടിവു നഩ്ഩിഩ്"}, "author": "எல்வன் பார்த்தசாரதி", "lang": "ta"}, {"label": "Translation", "title": "Journey", "text": "A chosen course may twist and bend,\nYet untold paths bring joys unpenned.", "author": "Elvan Parthasarathy", "lang": "en"}]'::jsonb
);

INSERT INTO quotes (id, tag, date, is_pinned, pin_expires_at, urai, notes, variants) VALUES (
  '4',
  'Perspective',
  '2026-03-02T10:00',
  FALSE,
  NULL,
  '',
  '',
  '[{"label": "Original", "title": "Perspective", "text": "No two shadows dance the same,\nTry to enjoy the rhythm.", "author": "Elvan Parthasarathy", "lang": "en"}, {"label": "Translation", "title": "பார்வை", "titleTransliterations": {"en": "Paarvai"}, "text": "எந்த இரு நிழல்களும் ஒரே மாதிரி நடனமாடுவதில்லை,\nஅதன் தாளத்தை ரசிக்க பழகு.", "transliterations": {"en": "Endha iru nizhalgalum ore maathiri nadanamaaduvathillai,\nAthan thaalaththai rasikka pazhagu."}, "author": "எல்வன் பார்த்தசாரதி", "lang": "ta"}]'::jsonb
);

INSERT INTO quotes (id, tag, date, is_pinned, pin_expires_at, urai, notes, variants) VALUES (
  '5',
  'Hope',
  '2026-03-02T14:00',
  FALSE,
  NULL,
  '',
  '',
  '[{"label": "Original", "title": "Hope", "text": "Every locked door opens only\nto reveal another passage.", "author": "Elvan Parthasarathy", "lang": "en"}, {"label": "Translation", "title": "நம்பிக்கை", "titleTransliterations": {"en": "Nambikkai"}, "text": "ஒவ்வொரு பூட்டிய கதவும் திறப்பது,\nமற்றொரு பாதையை காட்டவே.", "transliterations": {"en": "Ovvoru poottiya kathavum thirappathu,\nMatroru paathaiyai kaattave."}, "author": "எல்வன் பார்த்தசாரதி", "lang": "ta"}]'::jsonb
);